import sys

def solve(n, arr, queries):
    import math
    LOG = max(1, math.floor(math.log2(n)) + 1) if n > 0 else 1
    sparse = [arr[:]] + [[0]*n for _ in range(LOG-1)]
    for j in range(1, LOG):
        for i in range(n - (1 << j) + 1):
            sparse[j][i] = min(sparse[j-1][i], sparse[j-1][i + (1 << (j-1))])
    def rmq(l, r):
        k = int(math.log2(r - l + 1))
        return min(sparse[k][l], sparse[k][r - (1 << k) + 1])
    return "\n".join(str(rmq(l, r)) for l, r in queries)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    arr = list(map(int, data[idx:idx+n])); idx += n
    q = int(data[idx]); idx += 1
    queries = [(int(data[idx+i*2]), int(data[idx+i*2+1])) for i in range(q)]
    print(solve(n, arr, queries))

